package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen3Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValue_Integer() {
        Integer val = 10;
        frequency.addValue(val);
        assertEquals("Frequency count for Integer should be 1", 1L, frequency.getCount(val));
        assertEquals("Total sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValue_String() {
        String val = "test";
        frequency.addValue(val);
        assertEquals("Frequency count for String should be 1", 1L, frequency.getCount(val));
        assertEquals("Total sum frequency should be 1", 1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValue_Double() {
        // Double implements Comparable
        Double val = 10.5;
        frequency.addValue(val);
        assertEquals("Frequency count for Double should be 1", 1L, frequency.getCount(val));
    }

    @Test
    public void testAddValue_MultipleValues() {
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(1);

        assertEquals("Count for 1 should be 2", 2L, frequency.getCount(1));
        assertEquals("Count for 2 should be 1", 1L, frequency.getCount(2));
        assertEquals("Total sum frequency should be 3", 3L, frequency.getSumFreq());
    }

    @Test(expected = ClassCastException.class)
    public void testAddValue_NonComparableThrowsException() {
        // A non-comparable object (like a plain custom Object without Comparable)
        // will cause a ClassCastException when the method tries to cast (Comparable<?>) v
        class NonComparable {
            private final int id;
            NonComparable(int id) { this.id = id; }
        }

        frequency.addValue(new NonComparable(1));
    }

    @Test
    public void testAddValue_Null() {
        // Passing null to addValue(Object v) will result in (Comparable<?>) null
        // which is valid in Java, but the internal implementation of Frequency 
        // might handle nulls depending on how the underlying map works.
        // Most Frequency implementations treat null as a valid key or throw NPE.
        // Based on the signature, we test the behavior of passing null.
        try {
            frequency.addValue(null);
            // If it doesn't throw, we check if we can retrieve it
            // Note: Frequency usually uses a TreeMap/HashMap internally.
            // If it uses TreeMap, null might throw NPE.
        } catch (NullPointerException e) {
            // This is an acceptable outcome depending on the internal implementation
        }
    }
}
